mapper.select:
SELECT FROM ( SELECT receivable.customer_id AS customer, customer.customer_name, receivable.owner_id AS owner, receivable.owner_name, CASE WHEN receivable.due_date IS NULL THEN 'UNDATED' WHEN receivable.due_date >= #{query.snapshotDate} THEN 'CURRENT'
WHEN DATEDIFF(#{query.snapshotDate}, receivable.due_date) <= #{tier.days} THEN #{tier.code}
ELSE #{overflow.code} END AS aging_bucket, CASE WHEN receivable.due_date IS NULL THEN '未填写到期日' WHEN receivable.due_date >= #{query.snapshotDate} THEN '未逾期'
WHEN DATEDIFF(#{query.snapshotDate}, receivable.due_date) <= #{tier.days} THEN #{tier.name}
ELSE #{overflow.name} END AS aging_bucket_name, receivable.planned_amount, receivable.received_amount, receivable.outstanding_amount, 0 AS integrity_error FROM crm_receivable receivable INNER JOIN crm_customer customer ON customer.customer_id = receivable.customer_id AND customer.tenant_id = receivable.tenant_id AND customer.deleted = 0 WHERE receivable.tenant_id = #{tenantId} AND receivable.deleted = 0
) fact
